// 🟢 安全: 转义特殊字符
string safeUsername = username.Replace("\\", "\\5c")
                              .Replace("*", "\\2a")
                              .Replace("(", "\\28")
                              .Replace(")", "\\29")
                              .Replace("\0", "\\00");
```

