### 2. GORM 特定

```go
import "gorm.io/gorm"

// 危险: Raw 拼接
func search(db *gorm.DB, name string) []User {
    var users []User
    db.Raw("SELECT * FROM users WHERE name = '" + name + "'").Scan(&users)
    return users
}

// 危险: Where 字符串
func search(db *gorm.DB, name string) []User {
    var users []User
    db.Where("name = '" + name + "'").Find(&users)
    return users
}

// 安全: 参数化
func search(db *gorm.DB, name string) []User {
    var users []User
    db.Where("name = ?", name).Find(&users)
    return users
}

// 安全: 结构体条件
func search(db *gorm.DB, name string) []User {
    var users []User
    db.Where(&User{Name: name}).Find(&users)
    return users
}
```

