execFile('cat', [filename], (err, stdout) => {  // ✓ 使用参数数组
    res.send(stdout);
});

// 或使用 spawn 不带 shell
const { spawn } = require('child_process');
const child = spawn('cat', [filename]);  // ✓ shell=false (默认)
