// Controller代码
@PostMapping("/notice/add")
public String add(SysNotice notice) {
    // ❌ 如果SysNotice的属性是通过request.getParameter()获取的，会绕过XSS过滤
    String title = notice.getTitle();  // 没有被XSS过滤！
    return noticeService.insertNotice(notice);
