grep -rn "Route::get.*{.*}\|public function show" --include="*.php"

# 批量操作
grep -rn "function export\|function download\|function batch" --include="*.php"

# 资金操作
grep -rn "transfer\|payment\|refund\|balance" --include="*.php"

