__get()            // 读取不可访问属性时触发
__set()            // 写入不可访问属性时触发
__isset()          // 对不可访问属性调用isset/empty时触发
__unset()          // 对不可访问属性调用unset时触发
__invoke()         // 对象当函数调用时触发
