rename($old, $new);
parse_ini_file($file);
```

### 路径遍历防护

```php
// 危险字符
../          // 目录穿越
..\          // Windows目录穿越
..%2f        // URL编码
..%5c        // URL编码

// 防护方法
function secureFilePath($filename, $basedir) {
    // 移除危险字符
    $filename = str_replace(['../', '.\\', '%00'], '', $filename);

    // 拼接路径
    $filepath = $basedir . $filename;

    // 获取真实路径
    $realpath = realpath($filepath);

    // 验证是否在基础目录内
    if(strpos($realpath, realpath($basedir)) !== 0) {
        return false;
    }

    return $realpath;
}
```

